// Family `menu` — the option list (item, selectableItem, label, separator,
// group, shortcut, sub-trigger, item-indicator).
// Origin: ~12 parts repeated across dropdown/context/menubar/select/combobox.
//
// Decisions in docs/architecture.md §2 (orthogonal families), style families
// (tv with zero variants), state normalization (highlighted), and palette
// (palette kills colour duplication).
//
// Drift resolved — recorded in the port report:
//  - gap-1.5 (dropdown/context/menubar/select) vs gap-2 (combobox)
//    → unified to gap-2
//  - data-disabled:opacity-50 (only menubar) → applied to ALL via base
//  - data-[variant=destructive]: 6 declarations + dark theme block →
//    palette passed via className (e.g. className="palette-danger"),
//    base uses highlighted:bg-palette-soft / text-palette-accent which
//    resolve against whichever palette is active — no tone variant
//  - focus:*:[svg]:text-accent-foreground (context) vs
//    not-data-[variant=destructive]:focus:**:text-accent-foreground (dropdown)
//    → eliminated: palette redefines tokens, inheritance does the rest
//  - text-muted-foreground (label/shortcut/separator) → text-palette-accent/85
//    (the settled secondary-text value — AGENTS.md §"Secondary text")
//  - bg-border (separator) → bg-palette-line
//  - item-indicator: some without flex/size-4 → standardized with all
//  - label: px-2 py-1.5 (combobox) vs px-1.5 py-1 (others) → px-1.5 py-1.5
//  - label: font-medium (dropdown/context) vs none (combobox/select)
//    → font-medium (distinguishes label from item)
//
// Zero variants: the `indicator` variant became two members — `item`
// (px-1.5) and `selectableItem` (pe-8 ps-1.5, space for the check on the
// end side). menuCheckboxItem and menuRadioItem produced an identical
// string and were merged into `selectableItem`. The sub-trigger extends
// `item` (no indicator) — there is no selectable sub-trigger.
//
// Namespace object: a single `menu` export with all members.

import { tv } from "tailwind-variants";

// item is the central member. selectableItem and subTrigger derive from it
// via extend.
const item = tv({
    base: `
        relative flex cursor-default items-center gap-2 rounded-md py-1.5 text-sm
        px-1.5 outline-none select-none
        text-palette-accent/85 highlighted:bg-palette-soft highlighted:text-palette-contrast
        data-disabled:pointer-events-none data-disabled:opacity-50
        data-inset:ps-7
        [&_svg:not([class*='size-'])]:size-4
        [&_svg]:pointer-events-none [&_svg]:shrink-0
    `,
});

// selectableItem = item with space for the indicator (check) on the end side.
// Used by CheckboxItem, RadioItem, select item and combobox item.
// The pe-8 is not a style variation — it is a consequence of having an
// indicator, which is exactly why it is a member and not a variant.
const selectableItem = tv({
    extend: item,
    base: "pe-8 ps-1.5",
});

const label = tv({
    base: "text-palette-accent/85 px-1.5 py-1.5 text-xs font-medium data-inset:ps-7",
});

const separator = tv({
    base: "bg-palette-line -mx-1.5 my-1.5 h-px",
});

// Shortcut: secondary text (text-palette-accent/85 — the settled value).
// The original's focus colour change (group-focus/{name}:text-accent-foreground)
// has no equivalent without a secondary token; it distinguishes itself by
// size and position instead.
const shortcut = tv({
    base: "text-palette-accent/85 ms-auto text-xs tracking-widest",
});

// Sub-trigger = item + "popup open" state (data-popup-open).
const subTrigger = tv({
    extend: item,
    base: "data-popup-open:bg-palette-soft data-popup-open:text-palette-contrast",
});

const itemIndicator = tv({
    base: "pointer-events-none absolute inset-e-2 flex size-4 items-center justify-center",
});

export const menu = {
    item,
    selectableItem,
    label,
    separator,
    shortcut,
    subTrigger,
    itemIndicator,
};

// Menu parts factory — `createMenuParts(P)`.
//
// Takes a Base UI menu namespace (Menu or ContextMenu) and returns the styled
// React wrappers. This is the piece that lets dropdown-menu and context-menu
// share wrappers without coupling to the wrong namespace.
//
// Decisions in docs/architecture.md §2 (orthogonality) and style families.
//
// Why a factory and not a direct import of `Menu`:
// ContextMenu.Item === Menu.Item (14/14 parts identical at runtime). The
// behavioural adaptation happens inside Base UI via ContextMenuRootContext.
// Importing Menu directly would work today, but the factory protects against
// tomorrow: if Base UI ever diverges, each component inherits its own
// namespace's divergence instead of being silently pinned to Menu.

import type { Menu as MenuPrimitive } from "@base-ui/react/menu";
import { CheckIcon, ChevronRightIcon } from "lucide-react";
import type * as React from "react";
import { cn } from "@/lib/cn";
import { menu } from "../menu";
import { popup } from "../popup";

// Structural type of the namespace — only the parts the factory consumes.
// Root and Trigger are deliberately excluded: they differ between Menu and
// ContextMenu and stay in the specific component.
type MenuNamespace = {
    Item: typeof MenuPrimitive.Item;
    CheckboxItem: typeof MenuPrimitive.CheckboxItem;
    CheckboxItemIndicator: typeof MenuPrimitive.CheckboxItemIndicator;
    RadioGroup: typeof MenuPrimitive.RadioGroup;
    RadioItem: typeof MenuPrimitive.RadioItem;
    RadioItemIndicator: typeof MenuPrimitive.RadioItemIndicator;
    Group: typeof MenuPrimitive.Group;
    GroupLabel: typeof MenuPrimitive.GroupLabel;
    Separator: typeof MenuPrimitive.Separator;
    SubmenuRoot: typeof MenuPrimitive.SubmenuRoot;
    SubmenuTrigger: typeof MenuPrimitive.SubmenuTrigger;
    Portal: typeof MenuPrimitive.Portal;
    Positioner: typeof MenuPrimitive.Positioner;
    Popup: typeof MenuPrimitive.Popup;
};

export type MenuParts = ReturnType<typeof createMenuParts>;

export function createMenuParts(P: MenuNamespace) {
    function Item({
        className,
        inset,
        ...props
    }: MenuPrimitive.Item.Props & { inset?: boolean }) {
        return (
            <P.Item
                data-slot="menu-item"
                data-inset={inset}
                className={cn(menu.item(), className as string)}
                {...props}
            />
        );
    }

    function SelectableItem({
        className,
        inset,
        ...props
    }: MenuPrimitive.Item.Props & { inset?: boolean }) {
        return (
            <P.Item
                data-slot="menu-item"
                data-inset={inset}
                className={cn(menu.selectableItem(), className as string)}
                {...props}
            />
        );
    }

    function Label({
        className,
        inset,
        ...props
    }: MenuPrimitive.GroupLabel.Props & { inset?: boolean }) {
        return (
            <P.GroupLabel
                data-slot="menu-label"
                data-inset={inset}
                className={cn(menu.label(), className as string)}
                {...props}
            />
        );
    }

    function Separator({ className, ...props }: MenuPrimitive.Separator.Props) {
        return (
            <P.Separator
                data-slot="menu-separator"
                className={cn(menu.separator(), className as string)}
                {...props}
            />
        );
    }

    function Group({ ...props }: MenuPrimitive.Group.Props) {
        return <P.Group data-slot="menu-group" {...props} />;
    }

    function Shortcut({ className, ...props }: React.ComponentProps<"span">) {
        return (
            <span
                data-slot="menu-shortcut"
                className={cn(menu.shortcut(), className as string)}
                {...props}
            />
        );
    }

    function CheckboxItem({
        className,
        children,
        checked,
        inset,
        ...props
    }: MenuPrimitive.CheckboxItem.Props & { inset?: boolean }) {
        return (
            <P.CheckboxItem
                data-slot="menu-item"
                data-inset={inset}
                className={cn(menu.selectableItem(), className as string)}
                checked={checked}
                {...props}
            >
                <span
                    className={menu.itemIndicator()}
                    data-slot="menu-item-indicator"
                >
                    <P.CheckboxItemIndicator>
                        <CheckIcon />
                    </P.CheckboxItemIndicator>
                </span>
                {children}
            </P.CheckboxItem>
        );
    }

    function RadioGroup({ ...props }: MenuPrimitive.RadioGroup.Props) {
        return <P.RadioGroup data-slot="menu-radio-group" {...props} />;
    }

    function RadioItem({
        className,
        children,
        inset,
        ...props
    }: MenuPrimitive.RadioItem.Props & { inset?: boolean }) {
        return (
            <P.RadioItem
                data-slot="menu-item"
                data-inset={inset}
                className={cn(menu.selectableItem(), className as string)}
                {...props}
            >
                <span
                    className={menu.itemIndicator()}
                    data-slot="menu-item-indicator"
                >
                    <P.RadioItemIndicator>
                        <CheckIcon />
                    </P.RadioItemIndicator>
                </span>
                {children}
            </P.RadioItem>
        );
    }

    function SubTrigger({
        className,
        inset,
        children,
        ...props
    }: MenuPrimitive.SubmenuTrigger.Props & { inset?: boolean }) {
        return (
            <P.SubmenuTrigger
                data-slot="menu-sub-trigger"
                data-inset={inset}
                className={cn(menu.subTrigger(), className as string)}
                {...props}
            >
                {children}
                <ChevronRightIcon className="ms-auto rtl:rotate-180" />
            </P.SubmenuTrigger>
        );
    }

    function Content({
        className,
        align,
        alignOffset,
        side,
        sideOffset,
        ...props
    }: MenuPrimitive.Popup.Props &
        Pick<
            MenuPrimitive.Positioner.Props,
            "align" | "alignOffset" | "side" | "sideOffset"
        >) {
        return (
            <P.Portal>
                <P.Positioner
                    className="isolate z-50 outline-none"
                    align={align}
                    alignOffset={alignOffset}
                    side={side}
                    sideOffset={sideOffset}
                >
                    <P.Popup
                        data-slot="menu-content"
                        className={cn(
                            popup.content("z-50 outline-none"),
                            className as string,
                        )}
                        {...props}
                    />
                </P.Positioner>
            </P.Portal>
        );
    }

    function SubContent({
        className,
        side = "right",
        ...props
    }: React.ComponentProps<typeof Content>) {
        return (
            <Content
                data-slot="menu-sub-content"
                className={className}
                side={side}
                {...props}
            />
        );
    }

    return {
        // Sub is the primitive's SubmenuRoot, unstyled — it only groups. It
        // was initially missing: SubTrigger and SubContent existed, but
        // without the Root a submenu could not be mounted at all
        // (DropdownMenu.Sub / ContextMenu.Sub).
        Sub: P.SubmenuRoot,
        Item,
        SelectableItem,
        Label,
        Separator,
        Group,
        Shortcut,
        CheckboxItem,
        RadioGroup,
        RadioItem,
        SubTrigger,
        SubContent,
        Content,
    };
}
